using Alterverse.Characters;using Alterverse.Combat;using UnityEngine;
namespace Alterverse.UI
{
public sealed class PrototypeHUD:MonoBehaviour
{
private Health playerHealth;private BasicAttack basicAttack;private HeroMotor motor;private PlayerHeroAbilities abilities;private HeroIdentity identity;private Health enemyHealth;private GUIStyle titleStyle,textStyle,centerStyle,buttonStyle;private int joystickFinger=-1;private Vector2 joystickCenter,joystickKnob;private const float JoystickRadius=72f;
public void Initialize(Health player,VeyrAbilities legacyAbilities,Health enemy){playerHealth=player;enemyHealth=enemy;if(player!=null){basicAttack=player.GetComponent<BasicAttack>();motor=player.GetComponent<HeroMotor>();abilities=player.GetComponent<PlayerHeroAbilities>();identity=player.GetComponent<HeroIdentity>();}}
private void EnsureStyles(){titleStyle??=new GUIStyle(GUI.skin.label){fontSize=22,fontStyle=FontStyle.Bold};textStyle??=new GUIStyle(GUI.skin.label){fontSize=15,fontStyle=FontStyle.Bold};centerStyle??=new GUIStyle(GUI.skin.label){fontSize=16,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};buttonStyle??=new GUIStyle(GUI.skin.button){fontSize=14,fontStyle=FontStyle.Bold,alignment=TextAnchor.MiddleCenter};}
private void Update(){if(playerHealth!=null){abilities??=playerHealth.GetComponent<PlayerHeroAbilities>();identity??=playerHealth.GetComponent<HeroIdentity>();}HandleTouchJoystick();}
private void HandleTouchJoystick(){if(motor==null||Input.touchCount==0){if(joystickFinger>=0&&motor!=null)motor.SetMoveInput(Vector2.zero);joystickFinger=-1;return;}for(int i=0;i<Input.touchCount;i++){Touch touch=Input.GetTouch(i);Vector2 guiPos=new(touch.position.x,Screen.height-touch.position.y);if(touch.phase==TouchPhase.Began&&joystickFinger<0&&touch.position.x<Screen.width*.45f){joystickFinger=touch.fingerId;joystickCenter=guiPos;joystickKnob=guiPos;}if(touch.fingerId!=joystickFinger)continue;if(touch.phase==TouchPhase.Ended||touch.phase==TouchPhase.Canceled){joystickFinger=-1;motor.SetMoveInput(Vector2.zero);return;}Vector2 delta=Vector2.ClampMagnitude(guiPos-joystickCenter,JoystickRadius);joystickKnob=joystickCenter+delta;motor.SetMoveInput(new Vector2(delta.x,-delta.y)/JoystickRadius);}}
private void OnGUI(){EnsureStyles();float scale=Mathf.Clamp(Screen.height/900f,.72f,1.25f);GUI.matrix=Matrix4x4.Scale(new Vector3(scale,scale,1));float sw=Screen.width/scale,sh=Screen.height/scale;GUI.Box(new Rect(16,16,335,105),GUIContent.none);GUI.Label(new Rect(28,24,300,30),$"DIMENSIONS FRONT // {(identity!=null?identity.DisplayName.ToUpperInvariant():"HERO")}",titleStyle);if(playerHealth!=null){GUI.Label(new Rect(28,56,280,24),$"HP {playerHealth.Current:0} / {playerHealth.Max:0}",textStyle);DrawBar(new Rect(28,84,295,16),playerHealth.Normalized);}if(enemyHealth!=null&&!enemyHealth.IsDead){float width=320,x=(sw-width)*.5f;GUI.Box(new Rect(x,18,width,58),GUIContent.none);GUI.Label(new Rect(x+10,23,width-20,24),"ENEMY",centerStyle);DrawBar(new Rect(x+18,51,width-36,13),enemyHealth.Normalized);}DrawCombatButtons(sw,sh);DrawJoystick(sh);}
private void DrawCombatButtons(float sw,float sh){float attackSize=92,attackX=sw-120,attackY=sh-125;if(GUI.Button(new Rect(attackX,attackY,attackSize,attackSize),"ATTACK",buttonStyle)&&basicAttack!=null)basicAttack.TryAttack();DrawAbilityButton(new Rect(sw-220,sh-110,76,76),abilities!=null?Short(abilities.QName):"Q",abilities?.QRemaining??0,()=>abilities?.CastQ());DrawAbilityButton(new Rect(sw-195,sh-200,70,70),abilities!=null?Short(abilities.WName):"W",abilities?.WRemaining??0,()=>abilities?.CastW());DrawAbilityButton(new Rect(sw-112,sh-220,70,70),abilities!=null?Short(abilities.EName):"E",abilities?.ERemaining??0,()=>abilities?.CastE());DrawAbilityButton(new Rect(sw-292,sh-188,72,72),abilities!=null?"ULT\n"+Short(abilities.UltName):"ULT",abilities?.UltRemaining??0,()=>abilities?.CastUltimate());}
private static string Short(string value){if(string.IsNullOrEmpty(value))return "?";return value.Length<=9?value.ToUpperInvariant():value.Substring(0,9).ToUpperInvariant();}private void DrawAbilityButton(Rect rect,string label,float cooldown,System.Action action){string text=cooldown<=.05f?label:$"{label}\n{cooldown:0.0}";bool old=GUI.enabled;GUI.enabled=cooldown<=.05f;if(GUI.Button(rect,text,buttonStyle))action?.Invoke();GUI.enabled=old;}
private void DrawJoystick(float sh){Vector2 center=joystickFinger>=0?joystickCenter/GUI.matrix.m00:new Vector2(115,sh-115),knob=joystickFinger>=0?joystickKnob/GUI.matrix.m00:center;GUI.Box(new Rect(center.x-72,center.y-72,144,144),GUIContent.none);GUI.Box(new Rect(knob.x-30,knob.y-30,60,60),"MOVE");}private static void DrawBar(Rect rect,float normalized){GUI.Box(rect,GUIContent.none);float fill=Mathf.Clamp01(normalized)*(rect.width-4);GUI.Box(new Rect(rect.x+2,rect.y+2,fill,rect.height-4),GUIContent.none);}
}
}
